def populate_demo_dataset(raw_root: Path, overwrite: bool = False) -> Dict[str, int]:
    stats: Dict[str, int] = {}
    for label, texts in DEMO_TEXTS.items():
        target_dir = raw_root / label
        target_dir.mkdir(parents=True, exist_ok=True)
        written = 0
        for idx, text in enumerate(texts, start=1):
            file_path = target_dir / f"demo_{idx:03d}.txt"
            if file_path.exists() and not overwrite:
                continue
            file_path.write_text(text, encoding="utf-8")
            written += 1
        stats[label] = written
    return stats
